import sys

def resolve_type(t, types):
    while t in types and types[t] != t:
        t = types[t]
    return t

def apply_dereference(t):
    if t == 'void':
        return 'errtype'
    if t == 'errtype':
        return 'errtype'
    if t.startswith('&'):
        return t[1:]
    if t.endswith('*'):
        return t[:-1]
    return 'errtype'

def apply_pointer(t):
    return t + '*'

def main():
    import sys
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    types = {}
    results = []

    for i in range(1, n + 1):
        line = input[i]
        if line.startswith('typedef'):
            _, A, B = line.split()
            resolved_A = resolve_type(A, types)
            types[B] = resolved_A
        elif line.startswith('typeof'):
            _, A = line.split()
            current_type = resolve_type(A, types)
            asterisks = 0
            while current_type.startswith('&'):
                current_type = apply_dereference(current_type)
            while current_type.endswith('*'):
                asterisks += 1
                current_type = current_type[:-1]
            if current_type == 'void':
                results.append('void' + '*' * asterisks)
            else:
                results.append('errtype')

    for result in results:
        print(result)

main()
